 dlg=('Work talk',[('Ana','Are shorter meetings likely to spread?','Reuniões mais curtas tendem a se espalhar?'),('Leo','Yes. Nevertheless, some managers worry.','Sim. Mesmo assim, alguns gerentes se preocupam.'),('Ana','Do you remember trying a no-meeting day?','Lembra de ter tentado um dia sem reuniões?'),('Leo','I do. And I remembered to ask for feedback.','Lembro. E lembrei de pedir feedback.')]),
 speak_=[('Use nevertheless.','Use.','Nevertheless, I will try.'),('Use likely to.','Use.','It is likely to work.'),('Use bring together.','Use.','The meeting brought us together.')],
 wr=('Write a 6-sentence paragraph on improving meetings at work.','Many firms are likely to adopt shorter meetings. Nevertheless, some managers worry about control. Furthermore, they fear losing time. Consequently, a few firms try pilot weeks first. One director remembers trying a no-meeting day. She remembered to ask staff for feedback.',['Usei **conectores**','Usei **likely to**','Usei **remember**'],'6 frases'),
